-- =====================================================================
-- ACADEMIA DE VENDAS · Script 5: fotos reais, kits completos e cards de WhatsApp
-- Pode ser executado de novo sem perder dados.
-- =====================================================================
alter table public.lancamentos add column if not exists capa_url text;
alter table public.lancamentos add column if not exists galeria jsonb not null default '[]'::jsonb;
alter table public.lancamentos add column if not exists kit jsonb;
alter table public.lancamentos add column if not exists lamina_url text;
alter table public.lancamentos add column if not exists guia_url text;

update public.lancamentos set capa_url = '/projetos/verya/capa.jpg', galeria = '[{"url": "/projetos/verya/fotos/1.jpg", "legenda": "Fachada"}, {"url": "/projetos/verya/fotos/2.jpg", "legenda": "Rooftop com piscina coberta"}, {"url": "/projetos/verya/fotos/3.jpg", "legenda": "Academia no 10º andar"}, {"url": "/projetos/verya/fotos/4.jpg", "legenda": "Studio decorado"}, {"url": "/projetos/verya/fotos/5.jpg", "legenda": "Planta do studio"}, {"url": "/projetos/verya/fotos/6.jpg", "legenda": "Entre Jardins e Pinheiros"}]'::jsonb, kit = '{"identificacao": [["Empreendimento", "Verya Jardins, Av. Rebouças, 1.444, esquina com Rua Cristiano Viana, São Paulo/SP"], ["Fase", "Pré-lançamento, com participação via SCP com unidade determinada"]], "alerta": null, "mapa": [["Investimento", "Investidor de renda passiva, quem quer diversificar fora da renda fixa", "Opção A", "Card 1 · \"Seu studio aluga. Você recebe.\""], ["Estilo de vida", "Quem viaja com frequência a SP, pais de estudantes, uso misto", "Opção B", "Card 2 · \"Seu endereço entre Jardins e Pinheiros.\""], ["Reaquecimento", "Lead morno, base antiga, contato sem resposta", "Opção C", "Card 3 · \"Condição antes da tabela pública.\""]], "numeros": [["Produto", "258 studios de 18,5 a 24,8 m², entrega prevista para julho de 2029."], ["Enquadramento", "182 unidades R2V (70,5%), 100% do 11º ao 27º andar, com total liberdade para locação Short Stay e plataformas como Airbnb. As demais são HIS2 (50) e HMP (26), com limite de renda do comprador."], ["Localização", "350 m do metrô Oscar Freire (Linha 4) e 5 minutos a pé da Rua Oscar Freire."], ["Condição", "20% de entrada no ato e saldo de 80% em até 33 parcelas mensais sem juros (tabela de referência de setembro de 2026; confirme a vigência)."], ["Renda estimada (R2V)", "cenário realista de R$ 7.800 líquidos/mês, cerca de 19,4% ao ano, com 80% de ocupação e diária média de R$ 470. Pessimista (60%): R$ 5.540/mês, 13,68% a.a. Otimista (90%): R$ 9.050/mês, 22,44% a.a."], ["Gestão", "opcional pela 360 Suítes, maior operação de Airbnb da América Latina, com mobília, decoração, manutenção e operação de locação."]], "regras": [], "pilula": {"tese": "Studio compacto em esquina da Av. Rebouças, entre Jardins e Pinheiros, a 350 m do metrô Oscar Freire. Unidades R2V liberadas para Short Stay e Airbnb, com gestão opcional da 360 Suítes. Entrada em pré-lançamento via SCP com unidade determinada, 20% de entrada e saldo em até 33x sem juros.", "publico": "O investidor do interior que quer patrimônio em São Paulo sem administrar nada à distância. Também funciona para quem busca diversificação fora da renda fixa, pais com filhos estudando ou trabalhando na capital e profissionais que viajam com frequência a SP e querem uso misto.", "gatilho": "A janela de pré-lançamento. As condições via SCP costumam ser mais vantajosas do que a tabela pública pós-lançamento, e as unidades R2V se concentram do 11º ao 27º andar. Os andares altos, com vista para os Jardins, tendem a sair primeiro. Use sempre a disponibilidade atualizada do espelho."}, "abordagens": [{"opcao": "A", "tese": "investimento", "titulo": "Investimento e rentabilidade", "quando": "primeiro contato com perfil investidor, ou quando o cliente pergunta sobre rendimento", "card": "Card 1 · Investimento (1:1)", "texto": "Olá, [Nome do Cliente]! Tudo bem?\n\nSeparei uma oportunidade que conversa com o que você busca em renda 📈\n\n🏙️ *Verya Jardins*: studios na Av. Rebouças, entre Jardins e Pinheiros\n🚇 350 m do metrô Oscar Freire\n🔑 Liberdade total para Airbnb e Short Stay, com gestão da 360 Suítes\n\nNo cenário realista do book (80% de ocupação), a estimativa é de *R$ 7.800 líquidos por mês*, cerca de *19% ao ano* 💰\n\n💳 Entrada de 20% e saldo em até 33x sem juros, ainda em condição de pré-lançamento.\n\nPosso te mandar a simulação da unidade [andar/metragem]?\n\n_Estimativas de mercado, sem garantia de rentabilidade._"}, {"opcao": "B", "tese": "moradia", "titulo": "Moradia e estilo de vida", "quando": "cliente que vai a SP com frequência, pais de estudantes, quem valoriza endereço e lazer", "card": "Card 2 · Estilo de vida (1:1)", "texto": "[Nome do Cliente], boa tarde! 😊\n\nImagina ter seu endereço em São Paulo numa esquina entre Jardins e Pinheiros?\n\n📍 Av. Rebouças, a 5 minutos a pé da Rua Oscar Freire\n🏊 Piscina coberta e sauna no rooftop, com vista para os Jardins\n🏋️ Andar inteiro de academia, coworking e lavanderia\n🛋️ Studios de 18 a 24,8 m², assinados pela Nura Arquitetura e com interiores DP Barros\n\nDá para usar quando estiver na capital e deixar rendendo nos outros dias.\n\nQuer que eu te mostre as plantas? Te envio agora 📲"}, {"opcao": "C", "tese": "escassez", "titulo": "Reaquecimento de lead", "quando": "lead morno, contato antigo da base ou cliente que não respondeu às opções A e B", "card": "Card 3 · Urgência (1:1)", "texto": "Oi, [Nome do Cliente]! Aqui é [Nome do Corretor] 👋\n\nLembrei de você porque abriu uma oportunidade em São Paulo que ainda está em pré-lançamento, antes da tabela pública.\n\nStudio nos Jardins, liberado para Airbnb, entrada a partir de [Valor de Entrada].\n\nVale 5 minutos de conversa? Me diz o melhor horário ⏰"}], "continuidade": [{"titulo": "Follow-up sem resposta (48 horas depois)", "texto": "[Nome do Cliente], conseguiu ver o material do Verya? 😉\n\nSe quiser, preparo a simulação da unidade com entrada e parcelas. Leva dois minutos."}, {"titulo": "Cliente demonstrou interesse", "texto": "Perfeito, [Nome do Cliente]! Para te mandar a simulação certa, me confirma uma coisa:\n\nA ideia é renda com Airbnb, uso próprio ou os dois?"}, {"titulo": "Convite para conversa", "texto": "Ótimo! Tenho [dia] às [horário] ou [dia] às [horário] para te apresentar a unidade e tirar todas as dúvidas, por ligação ou vídeo. Qual fica melhor para você?"}], "antes": ["Confirme com a coordenação a tabela vigente e a disponibilidade atualizada do espelho de vendas.", "Identifique o perfil do cliente: investidor, uso próprio/misto ou lead morno. Isso define a mensagem e o card.", "Verifique o enquadramento adequado. Os cenários de renda e a liberdade para Airbnb valem para as unidades R2V. Para clientes que se enquadram em HIS2 ou HMP, a conversa é outra: acione a coordenação.", "Personalize todos os campos entre colchetes. Nunca envie a mensagem com colchetes visíveis."], "passos": ["Envie o texto primeiro. Ele abre a conversa e dá contexto.", "Logo em seguida, envie o card 1:1 correspondente. A imagem reforça a mensagem sem repetir tudo.", "No mesmo dia, publique o card 9:16 no seu Status. Isso alcança também quem você ainda não abordou individualmente.", "Quando o cliente responder, leve para a próxima etapa: simulação da unidade, plantas ou uma conversa por ligação ou vídeo.", "Com interesse confirmado, acione a coordenação para reservar a unidade no espelho e conduzir a formalização da participação via SCP."], "cadencia": [["Dia 0", "Primeiro contato conforme o perfil", "Opção A ou B + card 1:1"], ["Dia 0", "Publicação no Status", "Card 9:16 (Investimento ou Estilo de vida)"], ["Dia 2", "Sem resposta: follow-up curto", "Mensagem de follow-up + Card 3 (Urgência)"], ["Dia 5 a 7", "Ainda sem resposta: nova abordagem", "Opção C"], ["Após resposta", "Qualificar e convidar para conversa", "Mensagens de continuidade"], ["Semanal", "Manter presença no Status", "Alternar os três cards 9:16"]], "dicas": ["Leads antigos da sua base: comece direto pela Opção C. É uma abordagem leve, que reabre a conversa sem exigir que o cliente lembre do contato anterior.", "Melhores horários: entre 9h e 11h30 e entre 18h e 20h30 nos dias úteis. Evite mensagens comerciais aos domingos e após as 21h."], "faq": [{"pergunta": "O que é essa tal de SCP?", "resposta": "Na fase de pré-lançamento, antes do alvará e do registro do memorial de incorporação, a lei não permite o contrato tradicional de compra e venda. A entrada acontece por participação em Sociedade em Conta de Participação, já vinculada a uma unidade determinada (metragem, tipologia e posição no edifício). Com o registro do memorial, o contrato se converte em compromisso de compra e venda da mesma unidade. Oriente o cliente a validar o contrato com sua assessoria jurídica."}, {"pergunta": "E se o studio não alugar tanto?", "resposta": "Mostre os três cenários com transparência. Mesmo no pessimista, com 60% de ocupação, a estimativa é de R$ 5.540 líquidos por mês, cerca de 13,7% ao ano. Reforce que são estimativas de mercado, sem garantia de rentabilidade."}, {"pergunta": "Posso usar quando eu for a São Paulo?", "resposta": "Sim. O produto permite uso misto: hospedagem própria quando o cliente estiver na capital e locação nos demais períodos."}, {"pergunta": "Não conheço a construtora.", "resposta": "O Verya é realizado pela Chaincorp e pela MF7, incorporadoras com projetos em Pinheiros, Jardins, Perdizes, Vila Prudente e Jardim São Paulo, entre outros endereços centrais. Ofereça o material institucional e, se necessário, uma conversa com a coordenação de parcerias."}], "cards": [["1 · Investimento", "Seu studio aluga. Você recebe.", "R$ 7.800/mês estimados · 350 m do metrô · R2V · 360 Suítes", "Junto da Opção A; Status para perfil investidor"], ["2 · Estilo de vida", "Seu endereço entre Jardins e Pinheiros.", "350 m do metrô · Rooftop · Academia no 10º andar", "Junto da Opção B; Status institucional"], ["3 · Urgência", "Condição antes da tabela pública.", "20% de entrada · 33x sem juros · R2V limitadas", "Follow-up e Opção C"]], "boas_praticas": ["Fale em \"participação com unidade determinada\", e não em \"compra e venda\", enquanto o empreendimento estiver em fase de SCP.", "Rentabilidade é sempre estimativa. Nunca prometa ou garanta renda, ocupação ou valorização.", "Use \"R2V com total liberdade para locação Short Stay e plataformas como Airbnb\" ao descrever esse enquadramento.", "Uma mensagem por vez. Não envie as três opções ao mesmo cliente no mesmo dia.", "Sem listas de transmissão em massa para contatos frios. Priorize clientes com quem você já tem relacionamento.", "Registre cada contato e a resposta do cliente, para dar continuidade com a coordenação."], "aviso_legal": "Material de uso interno da rede de parceiros. Estimativas de mercado baseadas no book da incorporadora, sem garantia de rentabilidade. Empreendimento em pré-lançamento, sujeito às aprovações legais. Condições sujeitas à tabela vigente e à disponibilidade.", "cards_img": {"investimento": {"feed": "/projetos/verya/cards/investimento-feed.jpg", "stories": "/projetos/verya/cards/investimento-stories.jpg"}, "moradia": {"feed": "/projetos/verya/cards/moradia-feed.jpg", "stories": "/projetos/verya/cards/moradia-stories.jpg"}, "escassez": {"feed": "/projetos/verya/cards/escassez-feed.jpg", "stories": "/projetos/verya/cards/escassez-stories.jpg"}}}'::jsonb, lamina_url = '/projetos/verya/lamina.jpg', guia_url = '/projetos/verya/guia-do-kit.pdf', arte_feed_url = '/projetos/verya/cards/investimento-feed.jpg', arte_stories_url = '/projetos/verya/cards/investimento-stories.jpg', atualizado_em = now(), resumo = 'Studio compacto em esquina da Av. Rebouças, entre Jardins e Pinheiros, a 350 m do metrô Oscar Freire.' where id = 'verya';
insert into public.copies (lancamento_id, tese, texto) values ('verya', 'investimento', 'Olá, [Nome do Cliente]! Tudo bem?

Separei uma oportunidade que conversa com o que você busca em renda 📈

🏙️ *Verya Jardins*: studios na Av. Rebouças, entre Jardins e Pinheiros
🚇 350 m do metrô Oscar Freire
🔑 Liberdade total para Airbnb e Short Stay, com gestão da 360 Suítes

No cenário realista do book (80% de ocupação), a estimativa é de *R$ 7.800 líquidos por mês*, cerca de *19% ao ano* 💰

💳 Entrada de 20% e saldo em até 33x sem juros, ainda em condição de pré-lançamento.

Posso te mandar a simulação da unidade [andar/metragem]?

👉 Conheça o projeto: {link}

_Estimativas de mercado, sem garantia de rentabilidade._') on conflict (lancamento_id, tese) do update set texto = excluded.texto, atualizado_em = now();
insert into public.copies (lancamento_id, tese, texto) values ('verya', 'moradia', '[Nome do Cliente], boa tarde! 😊

Imagina ter seu endereço em São Paulo numa esquina entre Jardins e Pinheiros?

📍 Av. Rebouças, a 5 minutos a pé da Rua Oscar Freire
🏊 Piscina coberta e sauna no rooftop, com vista para os Jardins
🏋️ Andar inteiro de academia, coworking e lavanderia
🛋️ Studios de 18 a 24,8 m², assinados pela Nura Arquitetura e com interiores DP Barros

Dá para usar quando estiver na capital e deixar rendendo nos outros dias.

Quer que eu te mostre as plantas? Te envio agora 📲

👉 Conheça o projeto: {link}') on conflict (lancamento_id, tese) do update set texto = excluded.texto, atualizado_em = now();
insert into public.copies (lancamento_id, tese, texto) values ('verya', 'escassez', 'Oi, [Nome do Cliente]! Aqui é [Nome do Corretor] 👋

Lembrei de você porque abriu uma oportunidade em São Paulo que ainda está em pré-lançamento, antes da tabela pública.

Studio nos Jardins, liberado para Airbnb, entrada a partir de [Valor de Entrada].

Vale 5 minutos de conversa? Me diz o melhor horário ⏰

👉 Conheça o projeto: {link}') on conflict (lancamento_id, tese) do update set texto = excluded.texto, atualizado_em = now();
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('objecao', 'Verya: “O que é essa tal de SCP?”', 'Na fase de pré-lançamento, antes do alvará e do registro do memorial de incorporação, a lei não permite o contrato tradicional de compra e venda. A entrada acontece por participação em Sociedade em Conta de Participação, já vinculada a uma unidade determinada (metragem, tipologia e posição no edifício). Com o registro do memorial, o contrato se converte em compromisso de compra e venda da mesma unidade. Oriente o cliente a validar o contrato com sua assessoria jurídica.', 'verya', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id, status = 'publicada';
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('objecao', 'Verya: “E se o studio não alugar tanto?”', 'Mostre os três cenários com transparência. Mesmo no pessimista, com 60% de ocupação, a estimativa é de R$ 5.540 líquidos por mês, cerca de 13,7% ao ano. Reforce que são estimativas de mercado, sem garantia de rentabilidade.', 'verya', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id, status = 'publicada';
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('objecao', 'Verya: “Posso usar quando eu for a São Paulo?”', 'Sim. O produto permite uso misto: hospedagem própria quando o cliente estiver na capital e locação nos demais períodos.', 'verya', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id, status = 'publicada';

update public.lancamentos set capa_url = '/projetos/vici/capa.jpg', galeria = '[{"url": "/projetos/vici/fotos/1.jpg", "legenda": "Fachada"}, {"url": "/projetos/vici/fotos/2.jpg", "legenda": "Rooftop com piscina de borda infinita"}, {"url": "/projetos/vici/fotos/3.jpg", "legenda": "Studio Executivo"}, {"url": "/projetos/vici/fotos/4.jpg", "legenda": "Terraço lounge"}, {"url": "/projetos/vici/fotos/5.jpg", "legenda": "Coworking"}, {"url": "/projetos/vici/fotos/6.jpg", "legenda": "Pavimento tipo"}]'::jsonb, kit = '{"identificacao": [["Empreendimento", "Vici Faria Lima, Rua dos Cariris, 422, Pinheiros, São Paulo/SP"], ["Enquadramento", "Studios HIS-2 de 25 m², entrega prevista para abril de 2029"]], "alerta": null, "mapa": [["Investimento", "Investidor de patrimônio e valorização de longo prazo", "Opção A", "Card 1 · \"Faria Lima a R$ 13.200 o m².\""], ["Endereço e estilo de vida", "Quem valoriza localização, qualidade do ativo e liquidez futura", "Opção B", "Card 2 · \"O endereço que a Faria Lima disputa.\""], ["Reaquecimento", "Lead morno, base antiga, contato sem resposta", "Opção C", "Card 3 · \"Um dos últimos terrenos do eixo Faria Lima.\""]], "numeros": [["Produto", "340 studios HIS-2 de 25 m², em torre de uso misto com pavimentos corporativos, lazer e residencial. Terreno de 2.230 m², raro na região."], ["Localização", "Rua dos Cariris, 422, a 4 minutos a pé da Estação Faria Lima (Linha 4-Amarela), entre o Shopping Eldorado e a Av. Rebouças, vizinho do Faena e a poucos passos do HCor."], ["Preço", "de R$ 337 mil a R$ 383,6 mil (tabela de referência de setembro de 2026; confirme a vigência). Equivale a cerca de R$ 13.200 o m²."], ["Condição", "10% de entrada, 30% durante a obra e 60% financiados na entrega."], ["Tese de valorização", "spread projetado de +67% na liberação da unidade, no ano 13, frente à referência de R$ 22.000 o m² no mercado livre. TIR só da valorização de 10,3% a 16,8% a.a., conforme o cenário."], ["Retorno combinado", "somando a locação tradicional capitalizada ao CDI, a TIR combinada vai de 15,5% a 20,9% a.a., com múltiplo de 5,51x a 9,46x em 13 anos (análise MF7, mai/2026)."], ["Lazer", "rooftop com piscina de borda infinita, pool bar, sauna e solário; fitness, coworking, salão de festas, gourmet, terraço lounge, espaço zen e pet place."]], "regras": [{"titulo": "A regra HIS-2 que todo corretor precisa explicar", "itens": ["Sem teto de renda para o investidor comprar, mas o investidor fora da faixa não pode morar no imóvel. O uso é para geração de renda via locação.", "Por 10 anos a partir do Habite-se, o aluguel é limitado a inquilinos com renda de até R$ 9.726 por mês (base 2026), sem passar de 30% da renda do inquilino. Short Stay e Airbnb são proibidos nesse período.", "Depois dos 10 anos, a unidade fica livre para venda a qualquer preço e para qualquer comprador, e para aluguel livre, inclusive de curta duração. É aí que o spread se realiza.", "O FGTS não pode amortizar nem quitar o saldo devedor dessa unidade, e a matrícula fica gravada com a destinação HIS-2."]}], "pilula": {"tese": "A entrada mais acessível no eixo Faria Lima: studio de 25 m² a cerca de R$ 13.200 o m², em um dos últimos terrenos disponíveis da região. O investidor recebe locação tradicional durante o período HIS-2 e captura o spread para o mercado livre, projetado em +67%, quando a unidade se libera.", "publico": "O investidor de patrimônio com horizonte longo, que aceita a regra de 10 anos em troca de comprar Faria Lima com desconto relevante sobre o mercado livre. Também conversa com quem quer diversificar fora da renda fixa com um ativo real em São Paulo e com famílias que planejam patrimônio para a próxima geração.", "gatilho": "Escassez de terreno. O eixo Faria Lima, Rebouças e Eldorado tem landbank praticamente esgotado, e o preço por m² do Vici está bem abaixo da referência de mercado livre da região. A entrada de 10% torna o primeiro passo leve, e cada atualização de tabela encarece a mesma unidade."}, "abordagens": [{"opcao": "A", "tese": "investimento", "titulo": "Investimento e valorização", "quando": "primeiro contato com perfil investidor de longo prazo", "card": "Card 1 · Investimento (1:1)", "texto": "Olá, [Nome do Cliente]! Tudo bem?\n\nSeparei uma oportunidade rara para quem pensa em patrimônio 📈\n\n🏙️ *Vici Faria Lima*: studios de 25 m² em Pinheiros\n🚇 4 minutos a pé da Estação Faria Lima\n📐 Cerca de *R$ 13.200 o m²*, num eixo onde o mercado livre já pratica R$ 22.000\n\nA projeção da incorporadora indica um *spread de +67%* quando a unidade se libera das regras HIS-2, e uma TIR combinada de *15,5% a 20,9% ao ano* somando a locação 💰\n\n💳 Entrada de 10%, 30% na obra e 60% financiados na entrega.\n\nPosso te mandar a simulação completa?\n\n_Estimativas de mercado, sem garantia de rentabilidade._"}, {"opcao": "B", "tese": "moradia", "titulo": "Endereço e estilo de vida", "quando": "cliente que valoriza localização e qualidade do ativo; abordagem institucional", "card": "Card 2 · Endereço e estilo de vida (1:1)", "texto": "[Nome do Cliente], boa tarde! 😊\n\nJá pensou em ter um imóvel no endereço mais disputado de São Paulo?\n\n📍 Rua dos Cariris, entre o Shopping Eldorado e a Av. Rebouças\n🏊 Rooftop com piscina de borda infinita, pool bar e sauna\n💼 Coworking, fitness e terraço lounge\n✨ Vizinho do Faena e a poucos passos do HCor\n\nÉ o tipo de localização que não volta a aparecer: o eixo praticamente não tem mais terrenos.\n\nQuer que eu te mostre o projeto? Te envio agora 📲"}, {"opcao": "C", "tese": "escassez", "titulo": "Reaquecimento de lead", "quando": "lead morno, contato antigo da base ou cliente que não respondeu às opções A e B", "card": "Card 3 · Urgência (1:1)", "texto": "Oi, [Nome do Cliente]! Aqui é [Nome do Corretor] 👋\n\nLembrei de você porque saiu um dos últimos terrenos do eixo Faria Lima, e o studio começa em [Valor da Unidade].\n\nEntrada de 10%, saldo diluído na obra e financiamento na entrega.\n\nVale 5 minutos de conversa? Me diz o melhor horário ⏰"}], "continuidade": [{"titulo": "Follow-up sem resposta (48 horas depois)", "texto": "[Nome do Cliente], conseguiu ver o material do Vici Faria Lima? 😉\n\nSe quiser, preparo a simulação com entrada, parcelas de obra e a projeção de valorização. Leva dois minutos."}, {"titulo": "Cliente demonstrou interesse", "texto": "Perfeito, [Nome do Cliente]! Antes de te mandar a simulação, uma pergunta rápida:\n\nA ideia é investimento de longo prazo, ou você está pensando em morar? Pergunto porque a regra do HIS-2 muda conforme o perfil."}, {"titulo": "Convite para conversa", "texto": "Ótimo! Tenho [dia] às [horário] ou [dia] às [horário] para te apresentar a unidade e explicar a regra do HIS-2 com calma, por ligação ou vídeo. Qual fica melhor para você?"}], "antes": ["Confirme com a coordenação a tabela vigente e a disponibilidade de unidades.", "Identifique o perfil: investidor de longo prazo, cliente focado em endereço ou lead morno. Isso define a mensagem e o card.", "Qualifique o uso pretendido. Investidor fora da faixa de renda HIS-2 não pode morar no imóvel. Quem quer morar precisa ter renda familiar entre 3 e 6 salários mínimos. Na dúvida, acione a coordenação.", "Nunca ofereça o Vici como produto de Airbnb. Short Stay é proibido nos 10 primeiros anos a partir do Habite-se. Para esse perfil, o produto certo é o Verya Jardins.", "Personalize todos os campos entre colchetes. Nunca envie a mensagem com colchetes visíveis."], "passos": ["Envie o texto primeiro. Ele abre a conversa e dá contexto.", "Logo em seguida, envie o card 1:1 correspondente. A imagem reforça a mensagem sem repetir tudo.", "No mesmo dia, publique o card 9:16 no seu Status. Isso alcança também quem você ainda não abordou individualmente.", "Quando o cliente responder, explique a regra HIS-2 antes da simulação. Um cliente que entende a regra desde o início fecha com mais segurança e não desiste na assinatura.", "Com interesse confirmado, acione a coordenação para reservar a unidade e conduzir a proposta."], "cadencia": [["Dia 0", "Primeiro contato conforme o perfil", "Opção A ou B + card 1:1"], ["Dia 0", "Publicação no Status", "Card 9:16 (Investimento ou Endereço)"], ["Dia 2", "Sem resposta: follow-up curto", "Mensagem de follow-up + Card 3 (Urgência)"], ["Dia 5 a 7", "Ainda sem resposta: nova abordagem", "Opção C"], ["Após resposta", "Qualificar uso e convidar para conversa", "Mensagens de continuidade"], ["Semanal", "Manter presença no Status", "Alternar os três cards 9:16"]], "dicas": ["Leads antigos da sua base: comece direto pela Opção C. É uma abordagem leve, que reabre a conversa sem exigir que o cliente lembre do contato anterior.", "Melhores horários: entre 9h e 11h30 e entre 18h e 20h30 nos dias úteis. Evite mensagens comerciais aos domingos e após as 21h."], "faq": [{"pergunta": "O que é HIS-2? É habitação popular?", "resposta": "HIS-2 é uma categoria urbanística da Prefeitura de São Paulo que permite construir mais em regiões centrais em troca de unidades destinadas a famílias de renda média. Na prática, é o que viabiliza um studio na Faria Lima por cerca de R$ 13.200 o m². O padrão construtivo e o lazer são os mesmos de um empreendimento de mercado."}, {"pergunta": "Posso colocar no Airbnb?", "resposta": "Não nos 10 primeiros anos a partir do Habite-se. Nesse período, a locação é tradicional, para inquilinos dentro da faixa de renda da categoria. Depois disso, a unidade fica totalmente livre. Para quem quer renda de curta temporada desde já, apresente o Verya Jardins."}, {"pergunta": "10 anos não é tempo demais?", "resposta": "É exatamente o que gera o desconto de entrada. O investidor recebe aluguel durante o período e, na liberação, a unidade passa a valer como imóvel de mercado livre no eixo Faria Lima. A projeção da MF7 aponta TIR combinada de 15,5% a 20,9% ao ano em 13 anos. São estimativas, sem garantia."}, {"pergunta": "Posso usar o FGTS?", "resposta": "Não para amortizar ou quitar o saldo devedor dessa unidade. Oriente o cliente a planejar o financiamento sem contar com o FGTS."}, {"pergunta": "Não conheço a construtora.", "resposta": "O Vici é realizado pela Chaincorp e pela MF7, incorporadoras com projetos em Pinheiros, Jardins, Perdizes, Vila Prudente e Jardim São Paulo, entre outros endereços centrais. Ofereça o material institucional e, se necessário, uma conversa com a coordenação de parcerias."}], "cards": [["1 · Investimento", "Faria Lima a R$ 13.200 o m².", "+67% de spread · 4 min do metrô · TIR combinada 15,5% a 20,9% a.a. · HIS-2", "Junto da Opção A; Status para perfil investidor"], ["2 · Endereço e estilo de vida", "O endereço que a Faria Lima disputa.", "4 min do metrô · Rooftop · Vizinho do Faena", "Junto da Opção B; Status institucional"], ["3 · Urgência", "Um dos últimos terrenos do eixo Faria Lima.", "10% entrada · 30% obra · 60% financiados", "Follow-up e Opção C"]], "boas_praticas": ["Explique a regra HIS-2 logo no início. Transparência evita desistência e protege a sua comissão.", "Rentabilidade e valorização são sempre estimativas. Nunca prometa ou garanta renda, valorização ou prazo de revenda.", "Nunca venda o Vici como produto para Airbnb no período de restrição.", "Escreva sempre \"Vici Faria Lima\", nunca apenas \"VICI\" em caixa alta.", "Uma mensagem por vez. Não envie as três opções ao mesmo cliente no mesmo dia.", "Sem listas de transmissão em massa para contatos frios. Priorize clientes com quem você já tem relacionamento.", "Recomende ao cliente validar a operação com advogado ou contador de confiança."], "aviso_legal": "Material de uso interno da rede de parceiros. Projeções de valorização e TIR baseadas em análise MF7 de maio de 2026, estimativas de mercado sem garantia de rentabilidade. Unidades HIS-2 sujeitas às regras da categoria. Condições sujeitas à tabela vigente, à disponibilidade e à aprovação de crédito.", "cards_img": {"investimento": {"feed": "/projetos/vici/cards/investimento-feed.jpg", "stories": "/projetos/vici/cards/investimento-stories.jpg"}, "moradia": {"feed": "/projetos/vici/cards/moradia-feed.jpg", "stories": "/projetos/vici/cards/moradia-stories.jpg"}, "escassez": {"feed": "/projetos/vici/cards/escassez-feed.jpg", "stories": "/projetos/vici/cards/escassez-stories.jpg"}}}'::jsonb, lamina_url = '/projetos/vici/lamina.jpg', guia_url = '/projetos/vici/guia-do-kit.pdf', arte_feed_url = '/projetos/vici/cards/investimento-feed.jpg', arte_stories_url = '/projetos/vici/cards/investimento-stories.jpg', atualizado_em = now(), resumo = 'A entrada mais acessível no eixo Faria Lima: studio de 25 m² a cerca de R$ 13.200 o m², em um dos últimos terrenos disponíveis da região.' where id = 'vici';
insert into public.copies (lancamento_id, tese, texto) values ('vici', 'investimento', 'Olá, [Nome do Cliente]! Tudo bem?

Separei uma oportunidade rara para quem pensa em patrimônio 📈

🏙️ *Vici Faria Lima*: studios de 25 m² em Pinheiros
🚇 4 minutos a pé da Estação Faria Lima
📐 Cerca de *R$ 13.200 o m²*, num eixo onde o mercado livre já pratica R$ 22.000

A projeção da incorporadora indica um *spread de +67%* quando a unidade se libera das regras HIS-2, e uma TIR combinada de *15,5% a 20,9% ao ano* somando a locação 💰

💳 Entrada de 10%, 30% na obra e 60% financiados na entrega.

Posso te mandar a simulação completa?

👉 Conheça o projeto: {link}

_Estimativas de mercado, sem garantia de rentabilidade._') on conflict (lancamento_id, tese) do update set texto = excluded.texto, atualizado_em = now();
insert into public.copies (lancamento_id, tese, texto) values ('vici', 'moradia', '[Nome do Cliente], boa tarde! 😊

Já pensou em ter um imóvel no endereço mais disputado de São Paulo?

📍 Rua dos Cariris, entre o Shopping Eldorado e a Av. Rebouças
🏊 Rooftop com piscina de borda infinita, pool bar e sauna
💼 Coworking, fitness e terraço lounge
✨ Vizinho do Faena e a poucos passos do HCor

É o tipo de localização que não volta a aparecer: o eixo praticamente não tem mais terrenos.

Quer que eu te mostre o projeto? Te envio agora 📲

👉 Conheça o projeto: {link}') on conflict (lancamento_id, tese) do update set texto = excluded.texto, atualizado_em = now();
