insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('objecao', 'Vici: “O que é HIS-2? É habitação popular?”', 'HIS-2 é uma categoria urbanística da Prefeitura de São Paulo que permite construir mais em regiões centrais em troca de unidades destinadas a famílias de renda média. Na prática, é o que viabiliza um studio na Faria Lima por cerca de R$ 13.200 o m². O padrão construtivo e o lazer são os mesmos de um empreendimento de mercado.', 'vici', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id, status = 'publicada';
