update public.lancamentos set capa_url = '/projetos/pina/capa.jpg', galeria = '[{"url": "/projetos/pina/fotos/1.jpg", "legenda": "Fachada"}, {"url": "/projetos/pina/fotos/2.jpg", "legenda": "Deck"}, {"url": "/projetos/pina/fotos/3.jpg", "legenda": "Living do apartamento"}, {"url": "/projetos/pina/fotos/4.jpg", "legenda": "Studio"}, {"url": "/projetos/pina/fotos/5.jpg", "legenda": "Coworking"}, {"url": "/projetos/pina/fotos/6.jpg", "legenda": "Planta tipo"}]'::jsonb, kit = '{"identificacao": [["Empreendimento", "Pina 1875, Rua Apinajés, 1875, Perdizes, São Paulo/SP"], ["Produto", "72 unidades de 18 a 49 m², de studios a 2 dormitórios, entrega prevista para outubro de 2028"], ["Status", "Incorporação registrada em 08/04/2026, matrícula 130.152"]], "alerta": {"titulo": "Atenção antes de usar os números de renda", "texto": "Os cenários de renda deste kit vêm da análise da 360 Suítes, baseada em locação por temporada. O empreendimento também tem unidades HIS-2 e HMP, que seguem regras próprias de locação. Confirme com a coordenação o enquadramento da unidade antes de apresentar a renda estimada ao cliente."}, "mapa": [["Investimento", "Investidor de renda, quem quer gestão profissional sem trabalho operacional", "Opção A", "Card 1 · \"Studio em Perdizes. Renda com a 360 Suítes.\""], ["Endereço e estilo de vida", "Quem valoriza bairro, lazer e mobilidade", "Opção B", "Card 2 · \"Entre a Vila Madalena e Perdizes.\""], ["Reaquecimento", "Lead morno, base antiga, contato sem resposta", "Opção C", "Card 3 · \"Incorporação registrada. Entrega em 2028.\""]], "numeros": [["Produto", "72 unidades em torre única de 9 pavimentos, mais uma loja térrea: 12 studios garden, 35 studios, 17 unidades de 1 dormitório e 8 de 2 dormitórios."], ["Localização", "Rua Apinajés, 1875, a 3 quadras do Metrô Vila Madalena (Linha 2-Verde), a 8 minutos da PUC-SP, 13 minutos do Parque da Água Branca e perto do Allianz Parque."], ["Segurança jurídica", "incorporação registrada em 08/04/2026, matrícula 130.152. Entrega prevista para outubro de 2028."], ["Renda estimada do studio", "análise 360 Suítes com diária de R$ 460. Pessimista (60% de ocupação): R$ 2.800/mês, 11,60% a.a. Realista (83%): R$ 4.180/mês, 17,40% a.a. Otimista (92%): R$ 4.720/mês, 19,60% a.a."], ["Renda das demais tipologias", "1 dormitório de R$ 3.680 a R$ 6.176 por mês (11,70% a 19,70% a.a.); 2 dormitórios de R$ 5.396 a R$ 8.967 por mês (11,30% a 18,80% a.a.)."], ["Lazer", "estrutura completa no rooftop, casa de campo, coliving e coworking, fitness em andar exclusivo, lavanderia, pet place e deck."], ["Comissionamento", "PF 2% / PJ 4%, conforme Tabelão Chaincorp set/2026."]], "regras": [{"titulo": "Preços por tipologia (Tabelão Chaincorp set/2026)", "itens": ["Valores de referência, sujeitos a alteração sem aviso prévio e à disponibilidade. As condições de pagamento variam por unidade: confirme com a coordenação."], "tabela": [["Tipologia", "Metragem", "Preço"], ["Studio", "18 m²", "R$ 225.000"], ["Studio garden", "20 m²", "R$ 250.000"], ["Studio", "23 m²", "R$ 317.400"], ["1 dormitório", "26 m²", "R$ 358.800"], ["Studio garden", "35 m²", "R$ 437.500"], ["2 dormitórios", "49 m²", "R$ 784.000"]]}, {"titulo": "A regra HIS-2 e HMP que todo corretor precisa explicar", "itens": ["Investidor fora da faixa de renda pode comprar a unidade HIS-2, mas ela deve ser destinada à locação para público enquadrado, sem prazo final para essa obrigação.", "Se a unidade for vendida a um comprador enquadrado, passa a contar o prazo de 10 anos até a liberação total.", "Unidades HMP atendem famílias com renda de até 10 salários mínimos.", "Para o cliente que quer Airbnb, confirme antes qual unidade permite locação por temporada."]}], "pilula": {"tese": "Studio em Perdizes a 3 quadras do Metrô Vila Madalena, com incorporação já registrada e gestão de locação pela 360 Suítes. A entrada começa em R$ 225 mil, num bairro valorizado entre a Vila Madalena e a PUC-SP.", "publico": "O investidor que quer renda com gestão profissional e não quer administrar o imóvel à distância. Também conversa com pais de estudantes da PUC-SP e com quem busca o primeiro imóvel de investimento em São Paulo com tíquete acessível.", "gatilho": "São apenas 72 unidades em torre única, com incorporação registrada e entrega prevista para 2028. Cada atualização de tabela encarece a mesma unidade, e os studios de entrada são os primeiros a sair."}, "abordagens": [{"opcao": "A", "tese": "investimento", "titulo": "Investimento e rentabilidade", "quando": "primeiro contato com perfil investidor de renda", "card": "Card 1 · Investimento (1:1)", "texto": "Olá, [Nome do Cliente]! Tudo bem?\n\nSeparei uma oportunidade de renda em São Paulo 📈\n\n🏙️ *Pina 1875*: studios em Perdizes, a 3 quadras do Metrô Vila Madalena\n🔑 Gestão da locação pela 360 Suítes, sem trabalho para você\n\nNo cenário realista da operadora, a estimativa é de *R$ 4.180 líquidos por mês*, cerca de *17% ao ano* 💰\n\n💳 Studios a partir de *R$ 225 mil*\n🏗️ Incorporação registrada, entrega prevista para out/2028\n\nPosso te mandar a simulação da unidade?\n\n_Estimativas de mercado, sem garantia de rentabilidade._"}, {"opcao": "B", "tese": "moradia", "titulo": "Endereço e estilo de vida", "quando": "cliente que valoriza bairro, mobilidade e lazer", "card": "Card 2 · Endereço e estilo de vida (1:1)", "texto": "[Nome do Cliente], boa tarde! 😊\n\nJá pensou em ter um endereço entre a Vila Madalena e Perdizes?\n\n📍 A 3 quadras do metrô e a 8 minutos da PUC-SP\n🌿 Rooftop com casa de campo, deck e pet place\n💻 Coworking, coliving e fitness em andar exclusivo\n🛋️ Plantas de 18 a 49 m², do studio ao 2 dormitórios\n\nQuer que eu te mostre as plantas? Te envio agora 📲"}, {"opcao": "C", "tese": "escassez", "titulo": "Reaquecimento de lead", "quando": "lead morno, contato antigo da base ou cliente que não respondeu", "card": "Card 3 · Urgência (1:1)", "texto": "Oi, [Nome do Cliente]! Aqui é [Nome do Corretor] 👋\n\nLembrei de você porque tenho uma oportunidade em Perdizes com incorporação já registrada: studio a 3 quadras do metrô a partir de [Valor da Unidade].\n\nVale 5 minutos de conversa? Me diz o melhor horário ⏰"}], "continuidade": [{"titulo": "Follow-up sem resposta (48 horas depois)", "texto": "[Nome do Cliente], conseguiu ver o material do Pina 1875? 😉\n\nSe quiser, preparo a simulação da unidade com valores e renda estimada. Leva dois minutos."}, {"titulo": "Cliente demonstrou interesse", "texto": "Perfeito, [Nome do Cliente]! Para te mandar a simulação certa, me confirma uma coisa:\n\nA ideia é renda com locação, uso próprio ou os dois?"}, {"titulo": "Convite para conversa", "texto": "Ótimo! Tenho [dia] às [horário] ou [dia] às [horário] para te apresentar a unidade e tirar todas as dúvidas, por ligação ou vídeo. Qual fica melhor para você?"}], "antes": ["Confirme com a coordenação a tabela vigente e a disponibilidade de unidades.", "Identifique o perfil do cliente: investidor de renda, foco em endereço ou lead morno. Isso define a mensagem e o card.", "Confirme o enquadramento da unidade. HIS-2 e HMP têm regras próprias de locação. Só apresente os cenários de renda da 360 Suítes para unidades que permitem esse modelo.", "Personalize todos os campos entre colchetes. Nunca envie a mensagem com colchetes visíveis."], "passos": ["Envie o texto primeiro. Ele abre a conversa e dá contexto.", "Logo em seguida, envie o card 1:1 correspondente. A imagem reforça a mensagem sem repetir tudo.", "No mesmo dia, publique o card 9:16 no seu Status. Isso alcança também quem você ainda não abordou individualmente.", "Quando o cliente responder, entenda o objetivo dele. Renda, uso próprio ou os dois definem qual unidade e qual enquadramento fazem sentido.", "Com interesse confirmado, acione a coordenação para reservar a unidade e conduzir a proposta."], "cadencia": [["Dia 0", "Primeiro contato conforme o perfil", "Opção A ou B + card 1:1"], ["Dia 0", "Publicação no Status", "Card 9:16 (Investimento ou Endereço)"], ["Dia 2", "Sem resposta: follow-up curto", "Mensagem de follow-up + Card 3 (Urgência)"], ["Dia 5 a 7", "Ainda sem resposta: nova abordagem", "Opção C"], ["Após resposta", "Qualificar e convidar para conversa", "Mensagens de continuidade"], ["Semanal", "Manter presença no Status", "Alternar os três cards 9:16"]], "dicas": ["Leads antigos da sua base: comece direto pela Opção C. É uma abordagem leve, que reabre a conversa sem exigir que o cliente lembre do contato anterior.", "Melhores horários: entre 9h e 11h30 e entre 18h e 20h30 nos dias úteis. Evite mensagens comerciais aos domingos e após as 21h."], "faq": [{"pergunta": "Posso colocar no Airbnb?", "resposta": "Depende do enquadramento da unidade. Os cenários de renda foram elaborados pela 360 Suítes, mas unidades HIS-2 e HMP seguem regras específicas de locação. Confirme com a coordenação antes de responder."}, {"pergunta": "O que significa incorporação registrada?", "resposta": "Significa que o memorial de incorporação já está registrado em cartório (matrícula 130.152, desde 08/04/2026). É o que dá segurança jurídica para a venda na planta."}, {"pergunta": "E se não alugar tanto?", "resposta": "Mostre os três cenários com transparência. Mesmo no pessimista, com 60% de ocupação, a estimativa para o studio é de R$ 2.800 por mês, cerca de 11,6% ao ano. São estimativas, sem garantia."}, {"pergunta": "Não conheço a construtora.", "resposta": "A Chaincorp tem projetos em Pinheiros, Jardins, Perdizes, Vila Prudente e Jardim São Paulo, entre outros endereços centrais de São Paulo. Ofereça o material institucional e, se necessário, uma conversa com a coordenação de parcerias."}], "cards": [["1 · Investimento", "Studio em Perdizes. Renda com a 360 Suítes.", "R$ 4.180/mês estimados · 3 quadras do metrô · 83% de ocupação", "Junto da Opção A; Status para investidor"], ["2 · Endereço", "Entre a Vila Madalena e Perdizes.", "3 quadras do metrô · Rooftop · 8 min da PUC-SP", "Junto da Opção B; Status institucional"], ["3 · Urgência", "Incorporação registrada. Entrega em 2028.", "A partir de R$ 225 mil · 18 a 49 m² · out/2028", "Follow-up e Opção C"]], "boas_praticas": ["Renda é sempre estimativa. Nunca prometa ou garanta renda, ocupação ou valorização.", "Confirme o enquadramento antes de falar em Airbnb. Unidades HIS-2 e HMP têm regras próprias.", "Use a incorporação registrada como argumento de segurança, citando a matrícula quando o cliente pedir.", "Uma mensagem por vez. Não envie as três opções ao mesmo cliente no mesmo dia.", "Sem listas de transmissão em massa para contatos frios. Priorize clientes com quem você já tem relacionamento.", "Registre cada contato e a resposta do cliente, para dar continuidade com a coordenação."], "aviso_legal": "Material de uso interno da rede de parceiros. Cenários de renda da análise 360 Suítes, estimativas de mercado sem garantia de rentabilidade. Regras de locação variam conforme o enquadramento da unidade. Condições sujeitas à tabela vigente e à disponibilidade.", "cards_img": {"investimento": {"feed": "/projetos/pina/cards/investimento-feed.jpg", "stories": "/projetos/pina/cards/investimento-stories.jpg"}, "moradia": {"feed": "/projetos/pina/cards/moradia-feed.jpg", "stories": "/projetos/pina/cards/moradia-stories.jpg"}, "escassez": {"feed": "/projetos/pina/cards/escassez-feed.jpg", "stories": "/projetos/pina/cards/escassez-stories.jpg"}}}'::jsonb, lamina_url = '/projetos/pina/lamina.jpg', guia_url = '/projetos/pina/guia-do-kit.pdf', arte_feed_url = '/projetos/pina/cards/investimento-feed.jpg', arte_stories_url = '/projetos/pina/cards/investimento-stories.jpg', atualizado_em = now(), resumo = 'Studio em Perdizes a 3 quadras do Metrô Vila Madalena, com incorporação já registrada e gestão de locação pela 360 Suítes.', aviso = 'Os cenários de renda deste kit vêm da análise da 360 Suítes, baseada em locação por temporada. O empreendimento também tem unidades HIS-2 e HMP, que seguem regras próprias de locação. Confirme com a coordenação o enquadramento da unidade antes de apresentar a renda estimada ao cliente.' where id = 'pina';
insert into public.copies (lancamento_id, tese, texto) values ('pina', 'investimento', 'Olá, [Nome do Cliente]! Tudo bem?

Separei uma oportunidade de renda em São Paulo 📈

🏙️ *Pina 1875*: studios em Perdizes, a 3 quadras do Metrô Vila Madalena
🔑 Gestão da locação pela 360 Suítes, sem trabalho para você

No cenário realista da operadora, a estimativa é de *R$ 4.180 líquidos por mês*, cerca de *17% ao ano* 💰

💳 Studios a partir de *R$ 225 mil*
🏗️ Incorporação registrada, entrega prevista para out/2028

Posso te mandar a simulação da unidade?

👉 Conheça o projeto: {link}

_Estimativas de mercado, sem garantia de rentabilidade._') on conflict (lancamento_id, tese) do update set texto = excluded.texto, atualizado_em = now();
