update public.lancamentos set capa_url = '/projetos/blue/capa.jpg', galeria = '[{"url": "/projetos/blue/fotos/1.jpg", "legenda": "Fachada"}, {"url": "/projetos/blue/fotos/2.jpg", "legenda": "Piscina, vista aérea"}, {"url": "/projetos/blue/fotos/3.jpg", "legenda": "Piscina com prainha"}, {"url": "/projetos/blue/fotos/4.jpg", "legenda": "Fitness"}, {"url": "/projetos/blue/fotos/5.jpg", "legenda": "Living"}, {"url": "/projetos/blue/fotos/6.jpg", "legenda": "Planta de 3 dormitórios"}]'::jsonb, kit = '{"identificacao": [["Empreendimento", "Blue Park, Rua Parque Domingos Luís, 77, Jardim São Paulo, São Paulo/SP"], ["Produto", "72 apartamentos e gardens de 3 dormitórios, de 53 a 87 m²"], ["Entrega prevista", "Maio de 2027"]], "alerta": null, "mapa": [["Patrimônio", "Comprador de patrimônio e investidor de valorização na zona norte", "Opção A", "Card 1 · \"3 dormitórios em frente ao parque.\""], ["Moradia e estilo de vida", "Famílias, upgrade de moradia, quem quer área verde", "Opção B", "Card 2 · \"Viva em frente a um parque.\""], ["Reaquecimento", "Lead morno, base antiga, contato sem resposta", "Opção C", "Card 3 · \"Seu apartamento pronto em 2027.\""]], "numeros": [["Produto", "torre única de 15 pavimentos com 72 unidades e uma loja térrea. Apartamentos e gardens de 3 dormitórios, de 53 a 87 m²."], ["Diferencial raro", "possibilidade de unir unidades, retirando o caixilho entre living e terraço, com piso nivelado."], ["Localização", "em frente ao Parque Domingos Luís, a 2 minutos do Metrô Jardim São Paulo (Linha 1-Azul), perto do Shopping Center Norte, do Sesc Santana e do Hospital São Camilo."], ["Lazer", "áreas comuns entregues equipadas e decoradas: piscina adulto e infantil com prainha, solarium, sky lounge, fitness, brinquedoteca, playground, lavanderia, coworking e pet place."], ["Entrega", "prevista para maio de 2027, uma das mais próximas do portfólio."]], "regras": [{"titulo": "Enquadramentos e preços (Tabelão Chaincorp set/2026)", "itens": ["Valores sujeitos a alteração sem aviso prévio e à disponibilidade. Consulte o enquadramento específico de cada unidade. Unidades HMP atendem famílias com renda de até 10 salários mínimos."], "tabela": [["Metragem", "Enquadramento", "Preço", "R$/m²"], ["53 m²", "NR", "R$ 651.656", "R$ 12.295"], ["56 m²", "NR", "R$ 662.076", "R$ 11.823"], ["61 m² garden", "NR", "R$ 678.026", "R$ 11.115"], ["74 m² garden", "NR", "R$ 776.328", "R$ 10.491"], ["40 m² (2 dorms)", "HMP", "R$ 587.716", "R$ 14.693"], ["53 m²", "HMP", "R$ 794.337", "R$ 14.987"]]}], "pilula": {"tese": "Apartamento de 3 dormitórios em frente a um parque, a 2 minutos do metrô, num bairro tradicional da zona norte, com entrega prevista para 2027 e áreas comuns entregues decoradas. O metro quadrado das unidades NR parte de cerca de R$ 10.500.", "publico": "Famílias que querem espaço, verde e mobilidade, casais em upgrade de moradia e investidores de patrimônio que buscam um 3 dormitórios com boa liquidez na zona norte.", "gatilho": "A entrega está próxima, em maio de 2027, e são apenas 72 unidades. Gardens e plantas que permitem unir unidades são as primeiras a sair."}, "abordagens": [{"opcao": "A", "tese": "investimento", "titulo": "Patrimônio e valorização", "quando": "comprador de patrimônio ou investidor de longo prazo", "card": "Card 1 · Patrimônio (1:1)", "texto": "Olá, [Nome do Cliente]! Tudo bem?\n\nSeparei uma oportunidade rara na zona norte de São Paulo 🏡\n\n🌳 *Blue Park*: em frente ao Parque Domingos Luís\n🚇 2 minutos do Metrô Jardim São Paulo\n🛏️ Apartamentos de 3 dormitórios a partir de *R$ 651 mil*\n🗓️ Entrega prevista para maio de 2027\n\nÉ um 3 dormitórios com metrô, parque e bairro tradicional, uma combinação que valoriza e tem saída.\n\nPosso te mandar as plantas e a tabela?"}, {"opcao": "B", "tese": "moradia", "titulo": "Moradia e estilo de vida", "quando": "famílias e upgrade de moradia", "card": "Card 2 · Moradia e estilo de vida (1:1)", "texto": "[Nome do Cliente], boa tarde! 😊\n\nJá imaginou abrir a janela e ver um parque?\n\n🌳 Em frente ao Parque Domingos Luís\n🏊 Piscina com prainha, sky lounge e brinquedoteca\n🛏️ 3 dormitórios e gardens de 61 e 74 m²\n🔓 Possibilidade rara de unir unidades\n\nQuer que eu te mostre as plantas? Te envio agora 📲"}, {"opcao": "C", "tese": "escassez", "titulo": "Reaquecimento de lead", "quando": "lead morno, contato antigo da base ou cliente que não respondeu", "card": "Card 3 · Urgência (1:1)", "texto": "Oi, [Nome do Cliente]! Aqui é [Nome do Corretor] 👋\n\nLembrei de você: tenho um 3 dormitórios em frente a um parque, a 2 minutos do metrô, com entrega prevista para 2027, a partir de [Valor da Unidade].\n\nVale 5 minutos de conversa? Me diz o melhor horário ⏰"}], "continuidade": [{"titulo": "Follow-up sem resposta (48 horas depois)", "texto": "[Nome do Cliente], conseguiu ver o material do Blue Park? 😉\n\nSe quiser, preparo uma simulação com a unidade que mais combina com a sua família."}, {"titulo": "Cliente demonstrou interesse", "texto": "Perfeito, [Nome do Cliente]! Para eu te mandar as opções certas:\n\nÉ para morar com a família ou como investimento?"}, {"titulo": "Convite para visita ou conversa", "texto": "Ótimo! Tenho [dia] às [horário] ou [dia] às [horário] para te apresentar o projeto, por ligação, vídeo ou no decorado. Qual fica melhor?"}], "antes": ["Confirme com a coordenação a tabela vigente e a disponibilidade de unidades.", "Identifique o perfil: família, upgrade de moradia, patrimônio ou lead morno.", "Confira o enquadramento da unidade. Unidades HMP exigem renda familiar de até 10 salários mínimos.", "Personalize todos os campos entre colchetes. Nunca envie a mensagem com colchetes visíveis."], "passos": ["Envie o texto primeiro. Ele abre a conversa e dá contexto.", "Logo em seguida, envie o card 1:1 correspondente. A imagem reforça a mensagem sem repetir tudo.", "No mesmo dia, publique o card 9:16 no seu Status. Isso alcança também quem você ainda não abordou individualmente.", "Quando o cliente responder, entenda a composição da família. Número de filhos e uso do garden ajudam a escolher a planta certa.", "Com interesse confirmado, acione a coordenação para reservar a unidade e conduzir a proposta."], "cadencia": [["Dia 0", "Primeiro contato conforme o perfil", "Opção A ou B + card 1:1"], ["Dia 0", "Publicação no Status", "Card 9:16 (Patrimônio ou Moradia)"], ["Dia 2", "Sem resposta: follow-up curto", "Mensagem de follow-up + Card 3 (Urgência)"], ["Dia 5 a 7", "Ainda sem resposta: nova abordagem", "Opção C"], ["Após resposta", "Qualificar e convidar para conversa", "Mensagens de continuidade"], ["Semanal", "Manter presença no Status", "Alternar os três cards 9:16"]], "dicas": ["Leads antigos da sua base: comece direto pela Opção C. É uma abordagem leve, que reabre a conversa sem exigir que o cliente lembre do contato anterior.", "Melhores horários: entre 9h e 11h30 e entre 18h e 20h30 nos dias úteis. Evite mensagens comerciais aos domingos e após as 21h."], "faq": [{"pergunta": "Dá para unir dois apartamentos?", "resposta": "Sim, o projeto permite unir unidades, retirando o caixilho entre living e terraço, com piso nivelado. Confirme com a coordenação quais unidades permitem."}, {"pergunta": "O que é unidade HMP?", "resposta": "HMP é Habitação de Mercado Popular, uma categoria para famílias com renda de até 10 salários mínimos. As unidades NR não têm essa exigência."}, {"pergunta": "As áreas comuns vêm prontas?", "resposta": "Sim, as áreas comuns são entregues equipadas e decoradas."}, {"pergunta": "Não conheço a construtora.", "resposta": "A Chaincorp tem projetos em Pinheiros, Jardins, Perdizes, Vila Prudente e Jardim São Paulo, entre outros endereços centrais de São Paulo. Ofereça o material institucional e, se necessário, uma conversa com a coordenação de parcerias."}], "cards": [["1 · Patrimônio", "3 dormitórios em frente ao parque.", "A partir de R$ 651 mil · 2 min do metrô · mai/2027", "Junto da Opção A; Status institucional"], ["2 · Moradia", "Viva em frente a um parque.", "Parque · Lazer completo · Gardens", "Junto da Opção B; Status para famílias"], ["3 · Urgência", "Seu apartamento pronto em 2027.", "72 unidades · 3 dormitórios · 2 min do metrô", "Follow-up e Opção C"]], "boas_praticas": ["Valores são sempre de referência. Confirme a tabela vigente antes de enviar qualquer número.", "Confira o enquadramento antes de oferecer uma unidade HMP.", "Uma mensagem por vez. Não envie as três opções ao mesmo cliente no mesmo dia.", "Sem listas de transmissão em massa para contatos frios. Priorize clientes com quem você já tem relacionamento.", "Registre cada contato e a resposta do cliente, para dar continuidade com a coordenação."], "aviso_legal": "Material de uso interno da rede de parceiros. Valores do Tabelão Chaincorp set/2026, sujeitos a alteração sem aviso prévio e à disponibilidade. Entrega prevista para maio de 2027. Consulte o enquadramento específico de cada unidade.", "cards_img": {"investimento": {"feed": "/projetos/blue/cards/investimento-feed.jpg", "stories": "/projetos/blue/cards/investimento-stories.jpg"}, "moradia": {"feed": "/projetos/blue/cards/moradia-feed.jpg", "stories": "/projetos/blue/cards/moradia-stories.jpg"}, "escassez": {"feed": "/projetos/blue/cards/escassez-feed.jpg", "stories": "/projetos/blue/cards/escassez-stories.jpg"}}}'::jsonb, lamina_url = '/projetos/blue/lamina.jpg', guia_url = '/projetos/blue/guia-do-kit.pdf', arte_feed_url = '/projetos/blue/cards/investimento-feed.jpg', arte_stories_url = '/projetos/blue/cards/investimento-stories.jpg', atualizado_em = now(), resumo = 'Apartamento de 3 dormitórios em frente a um parque, a 2 minutos do metrô, num bairro tradicional da zona norte, com entrega prevista para 2027 e áreas comuns entregues decoradas.' where id = 'blue';
insert into public.copies (lancamento_id, tese, texto) values ('blue', 'investimento', 'Olá, [Nome do Cliente]! Tudo bem?

