insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('objecao', 'Blue Park: “Dá para unir dois apartamentos?”', 'Sim, o projeto permite unir unidades, retirando o caixilho entre living e terraço, com piso nivelado. Confirme com a coordenação quais unidades permitem.', 'blue', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id, status = 'publicada';
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('objecao', 'Blue Park: “O que é unidade HMP?”', 'HMP é Habitação de Mercado Popular, uma categoria para famílias com renda de até 10 salários mínimos. As unidades NR não têm essa exigência.', 'blue', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id, status = 'publicada';
insert into public.abordagens (etapa, titulo, texto, lancamento_id, autor_nome) values ('objecao', 'Blue Park: “As áreas comuns vêm prontas?”', 'Sim, as áreas comuns são entregues equipadas e decoradas.', 'blue', 'Chaincorp') on conflict ((lower(titulo))) do update set texto = excluded.texto, lancamento_id = excluded.lancamento_id, status = 'publicada';

